1	"use client";
2	
3	import { useMemo, useRef, useState } from "react";
4	
5	// Cmd/Ctrl-K palette over the actions the editor already has. It invents no
6	// new capability — every entry is a button that exists somewhere in the
7	// header or the sidebar. The value is that the fastest path to any of them
8	// stops depending on knowing where it lives.
9	//
10	// Keyboard contract (this is the whole point of the feature, so it is
11	// deliberately explicit rather than left to the browser):
12	//  - focus moves into the filter input on open, and back to whatever had it
13	//    on close — synchronously, so a command that focuses something itself
14	//    (Focus prompt box) still wins the race.
15	//  - Tab is trapped inside the dialog; Escape closes it.
16	//  - Arrow keys move a virtual selection; the input keeps real focus and
17	//    aria-activedescendant points at the highlighted row, which is the
18	//    combobox pattern screen readers already understand.
19	//
20	// The component mounts only while open, so there is no open/closed state to
21	// reset — and the selection is stored as a command ID and resolved to an
22	// index during render, so a list that re-filters under the user cannot leave
23	// a stale index pointing at the wrong row.
24	
25	export type Command = {
26	  id: string;
27	  label: string;
28	  /** Extra words that should match the filter but need not be shown. */
29	  keywords?: string;
30	  /** Right-aligned hint — a real key combination, or a state note. */
31	  hint?: string;
32	  disabled?: boolean;
33	  /** Why it is unavailable. Shown in place of the hint on a dimmed row. */
34	  disabledReason?: string;
35	  run: () => void;
36	};
37	
38	export type CommandGroup = { heading: string; commands: Command[] };
39	
40	const FOCUS_RING =
41	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
42	
43	function matches(cmd: Command, query: string): boolean {
44	  if (!query) return true;
45	  const haystack = `${cmd.label} ${cmd.keywords ?? ""}`.toLowerCase();
46	  // Every whitespace-separated term must appear somewhere — "pub site" finds
47	  // "Publish site" without needing the words adjacent.
48	  return query
49	    .toLowerCase()
50	    .split(/\s+/)
51	    .filter(Boolean)
52	    .every((term) => haystack.includes(term));
53	}
54	
55	export default function CommandPalette({
56	  onClose,
57	  groups,
58	}: {
59	  /** Closes the palette. Restoring focus is the caller's job, because the
60	      caller is the only one that knows what had focus before it opened —
61	      and it must happen before `run`, so a command that moves focus wins. */
62	  onClose: (run?: () => void) => void;
63	  groups: CommandGroup[];
64	}) {
65	  const [query, setQuery] = useState("");
66	  const [selectedId, setSelectedId] = useState<string | null>(null);
67	  const dialogRef = useRef<HTMLDivElement>(null);
68	  const listRef = useRef<HTMLDivElement>(null);
69	
70	  // Flattened, filtered, still carrying the heading each row sits under so the
71	  // list can render groups without a second pass over the source data.
72	  const rows = useMemo(() => {
73	    const out: { heading: string | null; cmd: Command }[] = [];
74	    for (const group of groups) {
75	      const hits = group.commands.filter((c) => matches(c, query));
76	      hits.forEach((cmd, i) => out.push({ heading: i === 0 ? group.heading : null, cmd }));
77	    }
78	    return out;
79	  }, [groups, query]);
80	
81	  // Derived, never stored: if the highlighted command filtered itself out (or
82	  // just became unavailable), the highlight falls to the first row that can
83	  // actually run, so Enter is never a no-op.
84	  const firstEnabled = rows.findIndex((r) => !r.cmd.disabled);
85	  const held = rows.findIndex((r) => r.cmd.id === selectedId && !r.cmd.disabled);
86	  const selected = held >= 0 ? held : firstEnabled;
87	
88	  function highlight(index: number) {
89	    setSelectedId(rows[index]?.cmd.id ?? null);
90	    listRef.current?.querySelector(`[data-index="${index}"]`)?.scrollIntoView({ block: "nearest" });
91	  }
92	
93	  function move(delta: number) {
94	    if (rows.length === 0) return;
95	    const start = selected < 0 ? (delta > 0 ? -1 : rows.length) : selected;
96	    for (let step = 1; step <= rows.length; step++) {
97	      const next = (start + delta * step + rows.length * step) % rows.length;
98	      if (!rows[next].cmd.disabled) {
99	        highlight(next);
100	        return;
101	      }
102	    }
103	  }
104	
105	  function onKeyDown(e: React.KeyboardEvent) {
106	    // The same chord that opened it closes it, and closes it the proper way —
107	    // through onClose, so focus goes back where it came from.
108	    if ((e.metaKey || e.ctrlKey) && !e.altKey && e.key.toLowerCase() === "k") {
109	      e.preventDefault();
110	      e.stopPropagation();
111	      onClose();
112	      return;
113	    }
114	    if (e.key === "Escape") {
115	      e.preventDefault();
116	      e.stopPropagation();
117	      onClose();
118	      return;
119	    }
120	    if (e.key === "Tab") {
121	      // Only the input and the close button are tabbable, so cycling between
122	      // them is the entire trap — focus can never reach the page behind.
123	      const focusable = dialogRef.current?.querySelectorAll<HTMLElement>(
124	        'input, button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])',
125	      );
126	      if (!focusable || focusable.length === 0) return;
127	      const first = focusable[0];
128	      const last = focusable[focusable.length - 1];
129	      if (e.shiftKey && document.activeElement === first) {
130	        e.preventDefault();
131	        last.focus();
132	      } else if (!e.shiftKey && document.activeElement === last) {
133	        e.preventDefault();
134	        first.focus();
135	      }
136	      return;
137	    }
138	    if (e.key === "ArrowDown") {
139	      e.preventDefault();
140	      move(1);
141	    } else if (e.key === "ArrowUp") {
142	      e.preventDefault();
143	      move(-1);
144	    } else if (e.key === "Home") {
145	      e.preventDefault();
146	      highlight(firstEnabled);
147	    } else if (e.key === "End") {
148	      e.preventDefault();
149	      for (let i = rows.length - 1; i >= 0; i--) {
150	        if (!rows[i].cmd.disabled) {
151	          highlight(i);
152	          break;
153	        }
154	      }
155	    } else if (e.key === "Enter") {
156	      e.preventDefault();
157	      const row = rows[selected];
158	      if (row && !row.cmd.disabled) onClose(row.cmd.run);
159	    }
160	  }
161	
162	  const activeId = selected >= 0 && rows[selected] ? `kodely-cmd-${rows[selected].cmd.id}` : undefined;
163	
164	  return (
165	    <div
166	      className="fixed inset-0 z-50 flex items-start justify-center bg-black/40 p-4 pt-[12vh]"
167	      onMouseDown={(e) => {
168	        if (e.target === e.currentTarget) onClose();
169	      }}
170	    >
171	      <div
172	        ref={dialogRef}
173	        role="dialog"
174	        aria-modal="true"
175	        aria-labelledby="kodely-cmd-title"
176	        onKeyDown={onKeyDown}
177	        className="flex w-full max-w-lg flex-col overflow-hidden rounded-xl border border-black/10 bg-white shadow-xl dark:border-white/10 dark:bg-neutral-900"
178	      >
179	        <h2 id="kodely-cmd-title" className="sr-only">
180	          Command palette
181	        </h2>
182	
183	        <div className="flex items-center gap-2 border-b border-black/10 px-3 py-2.5 dark:border-white/10">
184	          <label htmlFor="kodely-cmd-input" className="sr-only">
185	            Search commands
186	          </label>
187	          <input
188	            id="kodely-cmd-input"
189	            // Mounted only while open, so this is the whole of "focus the
190	            // input when the palette opens" — no effect required.
191	            autoFocus
192	            value={query}
193	            onChange={(e) => setQuery(e.target.value)}
194	            placeholder="Type a command…"
195	            autoComplete="off"
196	            spellCheck={false}
197	            role="combobox"
198	            aria-expanded="true"
199	            aria-controls="kodely-cmd-list"
200	            aria-activedescendant={activeId}
201	            aria-describedby="kodely-cmd-help"
202	            className={`min-w-0 flex-1 rounded-md bg-transparent px-1 py-0.5 text-sm outline-none placeholder:text-black/35 dark:placeholder:text-white/35 ${FOCUS_RING}`}
203	          />
204	          <button
205	            type="button"
206	            onClick={() => onClose()}
207	            aria-label="Close command palette"
208	            className={`shrink-0 rounded-md border border-black/15 px-2 py-0.5 text-xs text-black/60 hover:text-black dark:border-white/15 dark:text-white/60 dark:hover:text-white ${FOCUS_RING}`}
209	          >
210	            Esc
211	          </button>
212	        </div>
213	
214	        <div
215	          id="kodely-cmd-list"
216	          ref={listRef}
217	          role="listbox"
218	          aria-label="Commands"
219	          className="max-h-80 overflow-y-auto p-1.5"
220	        >
221	          {rows.length === 0 ? (
222	            <p className="px-2 py-6 text-center text-sm text-black/45 dark:text-white/45">
223	              No command matches “{query}”.
224	            </p>
225	          ) : (
226	            rows.map((row, i) => (
227	              <div key={row.cmd.id}>
228	                {row.heading && (
229	                  <div
230	                    role="presentation"
231	                    className="px-2 pb-1 pt-2 text-[11px] font-medium uppercase tracking-wide text-black/35 dark:text-white/35"
232	                  >
233	                    {row.heading}
234	                  </div>
235	                )}
236	                <div
237	                  id={`kodely-cmd-${row.cmd.id}`}
238	                  data-index={i}
239	                  role="option"
240	                  aria-selected={i === selected}
241	                  aria-disabled={row.cmd.disabled || undefined}
242	                  onMouseMove={() => {
243	                    if (!row.cmd.disabled && selected !== i) setSelectedId(row.cmd.id);
244	                  }}
245	                  onClick={() => {
246	                    if (!row.cmd.disabled) onClose(row.cmd.run);
247	                  }}
248	                  className={`flex cursor-default items-center justify-between gap-3 rounded-md px-2 py-1.5 text-sm ${
249	                    row.cmd.disabled
250	                      ? "text-black/30 dark:text-white/30"
251	                      : i === selected
252	                        ? "bg-black/10 dark:bg-white/10"
253	                        : "text-black/70 dark:text-white/70"
254	                  }`}
255	                >
256	                  <span className="min-w-0 truncate">{row.cmd.label}</span>
257	                  <span className="shrink-0 text-xs text-black/40 dark:text-white/40">
258	                    {row.cmd.disabled ? row.cmd.disabledReason : row.cmd.hint}
259	                  </span>
260	                </div>
261	              </div>
262	            ))
263	          )}
264	        </div>
265	
266	        <p
267	          id="kodely-cmd-help"
268	          className="border-t border-black/10 px-3 py-2 text-xs text-black/40 dark:border-white/10 dark:text-white/40"
269	        >
270	          ↑↓ to move · Enter to run · Esc to close
271	        </p>
272	      </div>
273	    </div>
274	  );
275	}
