1	"use client";
2	
3	// The preview pane, plus the width switcher above it.
4	//
5	// Generated sites are prompted to hold up down to 380px, and until now there
6	// was no way to check that without publishing and opening the result on a
7	// phone. So: three widths, a real pixel number next to them, and nothing else.
8	// No rounded phone shell, no notch, no rotate button — a device chrome would
9	// imply we are emulating a device, and we are not. We are changing a width.
10	//
11	// The iframe element is deliberately NOT re-keyed when the width changes, so
12	// switching widths resizes the live page rather than reloading it. That is the
13	// difference between testing a responsive layout and testing a page load.
14	
15	export type DeviceId = "desktop" | "tablet" | "mobile";
16	
17	export const DEVICES: { id: DeviceId; label: string; width: number | null; note: string }[] = [
18	  { id: "desktop", label: "Desktop", width: null, note: "full width" },
19	  { id: "tablet", label: "Tablet", width: 768, note: "768px" },
20	  // 380 rather than a real handset width: it is the floor the site generator
21	  // is told to support, so it is the number worth testing against.
22	  { id: "mobile", label: "Mobile", width: 380, note: "380px" },
23	];
24	
25	const FOCUS_RING =
26	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
27	
28	export default function PreviewFrame({
29	  src,
30	  reloadKey,
31	  device,
32	  onDeviceChange,
33	}: {
34	  src: string;
35	  reloadKey: number;
36	  device: DeviceId;
37	  onDeviceChange: (device: DeviceId) => void;
38	}) {
39	  const active = DEVICES.find((d) => d.id === device) ?? DEVICES[0];
40	
41	  return (
42	    <div className="flex h-full flex-col">
43	      <div className="flex flex-wrap items-center justify-between gap-2 border-b border-black/10 px-3 py-2 dark:border-white/10">
44	        <div
45	          role="group"
46	          aria-label="Preview width"
47	          className="flex items-center gap-1 rounded-lg border border-black/10 p-0.5 text-xs dark:border-white/10"
48	        >
49	          {DEVICES.map((d) => (
50	            <button
51	              key={d.id}
52	              type="button"
53	              onClick={() => onDeviceChange(d.id)}
54	              aria-pressed={device === d.id}
55	              className={`rounded-md px-2 py-1 ${FOCUS_RING} ${
56	                device === d.id
57	                  ? "bg-black text-white dark:bg-white dark:text-black"
58	                  : "text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
59	              }`}
60	            >
61	              {d.label}
62	            </button>
63	          ))}
64	        </div>
65	        {/* The number matters more than the label — "Mobile" is a guess,
66	            "380px" is a fact you can compare a bug report against. */}
67	        <span className="text-xs text-black/40 dark:text-white/40">
68	          Preview at {active.note}
69	        </span>
70	      </div>
71	
72	      {/* Constrained widths keep their real pixel size and let this container
73	          scroll if the pane is narrower — clamping them to the pane would
74	          make the "768px" label a lie, which is the one thing this control
75	          cannot afford. The scroll is contained here, never on the page. */}
76	      <div className="flex min-h-0 flex-1 justify-center overflow-auto">
77	        <iframe
78	          key={reloadKey}
79	          src={src}
80	          sandbox="allow-scripts allow-forms"
81	          title={`Live preview at ${active.note}`}
82	          style={active.width ? { width: active.width } : undefined}
83	          className={`h-full shrink-0 bg-white ${
84	            active.width
85	              ? "border-x border-black/10 dark:border-white/10"
86	              : "w-full border-0"
87	          }`}
88	        />
89	      </div>
90	    </div>
91	  );
92	}
