1	"use client";
2	
3	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
7	import BuildingOverlay from "./BuildingOverlay";
8	import BuildRating from "./BuildRating";
9	import BuildInterrupted, { type Interruption } from "./BuildInterrupted";
10	import CommandPalette, { type CommandGroup } from "./CommandPalette";
11	import PreviewFrame, { DEVICES, type DeviceId } from "./PreviewFrame";
12	
13	type Message = { role: string; content: string };
14	type BuildCheckpoint = { id: string; prompt: string; createdAt: string; filesWritten: number };
15	
16	type Props = {
17	  projectId: string;
18	  projectName: string;
19	  slug: string;
20	  published: boolean;
21	  initialFiles: Record<string, string>;
22	  initialMessages: Message[];
23	  initialBalance: number;
24	  /** This user's measured average credits per build — see lib/credits.ts. */
25	  avgBuildCredits: number;
26	};
27	
28	const SITES_BASE = process.env.NEXT_PUBLIC_SITES_BASE ?? "kodely.site";
29	
30	// Mirrors the publish route's own Host-based derivation (see the comment
31	// there) so the header's "live site" link always matches what publish
32	// actually returned, on staging or prod, without hardcoding either.
33	const FOCUS_RING =
34	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
35	
36	// Thrown for an `error` event the SERVER sent us, so the catch below can tell
37	// "the build failed and told us why" apart from "the pipe broke" — which are
38	// completely different messages to the user. Anything else that surfaces after
39	// streaming has begun is transport, not the build.
40	class BuildServerError extends Error {}
41	
42	// The platform never changes under us, so there is nothing to subscribe to —
43	// but reading navigator during render would make the server and client
44	// disagree. useSyncExternalStore with a server snapshot is the sanctioned way
45	// to say "assume Ctrl on the server, correct it on the client", and unlike a
46	// setState-in-effect it cannot produce a hydration mismatch on the way.
47	const NO_SUBSCRIBE = () => () => {};
48	const isMacClient = () => /Mac|iPhone|iPad|iPod/.test(navigator.userAgent);
49	const isMacServer = () => false;
50	
51	function liveSiteUrl(slug: string): string {
52	  if (typeof window === "undefined") return `https://${slug}.${SITES_BASE}`;
53	  const host = window.location.host;
54	  return host.includes("staging")
55	    ? `${window.location.origin}/api/site/${slug}`
56	    : `https://${slug}.${SITES_BASE}`;
57	}
58	
59	export default function Editor(props: Props) {
60	  const [messages, setMessages] = useState<Message[]>(props.initialMessages);
61	  const [files, setFiles] = useState(props.initialFiles);
62	  const [prompt, setPrompt] = useState("");
63	  const [busy, setBusy] = useState(false);
64	  const [status, setStatus] = useState<string | null>(null);
65	  const [error, setError] = useState<string | null>(null);
66	  const [balance, setBalance] = useState(props.initialBalance);
67	  // The build just finished in THIS session, so it can be rated. Deliberately
68	  // not restored on reload: rating a build you last saw yesterday is guesswork.
69	  const [lastBuildId, setLastBuildId] = useState<string | null>(null);
70	  const [previewNonce, setPreviewNonce] = useState(0);
71	  const [published, setPublished] = useState(props.published);
72	  const [publishing, setPublishing] = useState(false);
73	  const [view, setView] = useState<"preview" | "code" | "history">("preview");
74	  const [builds, setBuilds] = useState<BuildCheckpoint[] | null>(null);
75	  const [restoring, setRestoring] = useState<string | null>(null);
76	  const [activeFile, setActiveFile] = useState<string | null>(null);
77	  const [downloading, setDownloading] = useState(false);
78	  const [enhancing, setEnhancing] = useState(false);
79	  // The prompt as typed, held only while an expanded spec sits in the box.
80	  // Doubles as the "we're showing a spec" flag and as what Revert restores.
81	  const [enhancedFrom, setEnhancedFrom] = useState<string | null>(null);
82	  // A build that ended without finishing — stopped on purpose, or the stream
83	  // died. Not `error`: nothing went wrong, so it must not read like a failure.
84	  const [interruption, setInterruption] = useState<Interruption | null>(null);
85	  const [device, setDevice] = useState<DeviceId>("desktop");
86	  const [paletteOpen, setPaletteOpen] = useState(false);
87	  // Abort has been requested but the stream hasn't unwound yet. Rendered
88	  // state, not just the ref below, so the button can actually go dead.
89	  const [stopping, setStopping] = useState(false);
90	  const streamingReply = useRef("");
91	  // Aborting this is what the Stop button does; the route's stream cancel()
92	  // sees the disconnect and aborts the model call on the server side.
93	  const abortRef = useRef<AbortController | null>(null);
94	  const stopRequested = useRef(false);
95	  const promptRef = useRef<HTMLTextAreaElement>(null);
96	  const paletteTriggerRef = useRef<HTMLButtonElement>(null);
97	  // What had focus when the palette opened, so closing can hand it back.
98	  const paletteReturn = useRef<HTMLElement | null>(null);
99	  const router = useRouter();
100	
101	  const modKey = useSyncExternalStore(NO_SUBSCRIBE, isMacClient, isMacServer) ? "⌘" : "Ctrl";
102	
103	  async function refreshFiles() {
104	    const res = await fetch(`/api/projects/${props.projectId}`);
105	    const body = await res.json();
106	    setFiles(
107	      Object.fromEntries(
108	        (body.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
109	      ),
110	    );
111	    setPreviewNonce((n) => n + 1);
112	  }
113	
114	  async function openHistory() {
115	    setView("history");
116	    const res = await fetch(`/api/projects/${props.projectId}/builds`);
117	    const body = await res.json();
118	    setBuilds(body.builds ?? []);
119	  }
120	
121	  async function restore(buildId: string) {
122	    if (!confirm("Restore this checkpoint? Your current draft will be replaced.")) return;
123	    setRestoring(buildId);
124	    setError(null);
125	    try {
126	      const res = await fetch(`/api/projects/${props.projectId}/builds/${buildId}/restore`, {
127	        method: "POST",
128	      });
129	      const body = await res.json();
130	      if (!res.ok) throw new Error(body?.error ?? "Restore failed.");
131	      const res2 = await fetch(`/api/projects/${props.projectId}`);
132	      const body2 = await res2.json();
133	      const nextFiles: Record<string, string> = Object.fromEntries(
134	        (body2.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
135	      );
136	      setFiles(nextFiles);
137	      setPreviewNonce((n) => n + 1);
138	      setView("preview");
139	    } catch (err) {
140	      setError(err instanceof Error ? err.message : "Restore failed.");
141	    } finally {
142	      setRestoring(null);
143	    }
144	  }
145	
146	  // The foundation means source files are never empty — "first build" means
147	  // no chat history yet, matching the same signal the generate route uses.
148	  const isFirstBuild = messages.length === 0;
149	
150	  // If the visitor typed a prompt on the homepage before hitting the auth
151	  // wall, that prompt survives login/signup in sessionStorage — fire it
152	  // automatically the moment they land in their new project, instead of
153	  // making them retype what they already told us.
154	  useEffect(() => {
155	    if (!isFirstBuild) return;
156	    let pending: string | null = null;
157	    let pendingImage: string | null = null;
158	    try {
159	      pending = sessionStorage.getItem(PENDING_PROMPT_KEY);
160	      pendingImage = sessionStorage.getItem(PENDING_PROMPT_IMAGE_KEY);
161	    } catch {}
162	    if (!pending) return;
163	    try {
164	      sessionStorage.removeItem(PENDING_PROMPT_KEY);
165	      sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
166	    } catch {}
167	    send(pending, pendingImage ?? undefined);
168	    // Runs once on mount only — send() is intentionally not a dependency.
169	    // eslint-disable-next-line react-hooks/exhaustive-deps
170	  }, []);
171	
172	  async function send(overrideText?: string, image?: string) {
173	    const text = (overrideText ?? prompt).trim();
174	    if (!text || busy) return;
175	    if (balance <= 0) {
176	      setError("You're out of credits. Top up to keep building.");
177	      return;
178	    }
179	
180	    setBusy(true);
181	    setError(null);
182	    setInterruption(null);
183	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
184	    setMessages((m) => [...m, { role: "user", content: text }]);
185	    setPrompt("");
186	    setEnhancedFrom(null);
187	    streamingReply.current = "";
188	    stopRequested.current = false;
189	    const controller = new AbortController();
190	    abortRef.current = controller;
191	
192	    // Set once the first byte of the stream lands. After that point any
193	    // failure is the connection, not the request — which is what lets us tell
194	    // "couldn't start" apart from "died halfway".
195	    let streamStarted = false;
196	    // A `done` or `error` event. The route always sends one of them unless it
197	    // saw the client go away, so a stream that closes without either IS the
198	    // signature of a dropped connection.
199	    let sawTerminal = false;
200	    let touchedFiles = false;
201	
202	    try {
203	      const res = await fetch("/api/generate", {
204	        method: "POST",
205	        headers: { "Content-Type": "application/json" },
206	        body: JSON.stringify({ projectId: props.projectId, prompt: text, image }),
207	        signal: controller.signal,
208	      });
209	
210	      if (!res.ok || !res.body) {
211	        const body = await res.json().catch(() => ({}));
212	        throw new Error(body?.error ?? "The build failed to start.");
213	      }
214	
215	      const reader = res.body.getReader();
216	      const decoder = new TextDecoder();
217	      let buffer = "";
218	
219	      while (true) {
220	        const { done, value } = await reader.read();
221	        if (done) break;
222	        streamStarted = true;
223	        buffer += decoder.decode(value, { stream: true });
224	
225	        const parts = buffer.split("\n\n");
226	        buffer = parts.pop() ?? "";
227	
228	        for (const part of parts) {
229	          if (!part.startsWith("data: ")) continue;
230	          const event = JSON.parse(part.slice(6));
231	
232	          if (event.type === "text") {
233	            streamingReply.current += event.text;
234	          } else if (event.type === "progress" || event.type === "status") {
235	            // Both drive the same line. `progress` comes from a real tool call,
236	            // `status` from a phase the route knows about (a repair pass).
237	            setStatus(event.text);
238	          } else if (event.type === "file") {
239	            // On the SDK engine these all arrive at once after the build, so
240	            // they are a completion signal, not live progress — the progress
241	            // line above is what the user actually watches.
242	            touchedFiles = true;
243	          } else if (event.type === "done") {
244	            sawTerminal = true;
245	            setBalance(event.remaining);
246	            setStatus(null);
247	            setLastBuildId(event.buildId ?? null);
248	          } else if (event.type === "error") {
249	            sawTerminal = true;
250	            throw new BuildServerError(event.message);
251	          }
252	        }
253	      }
254	
255	      if (!sawTerminal) {
256	        // The pipe closed mid-build. Nothing was thrown, no error arrived —
257	        // this is exactly the silent stop the user used to be left staring at.
258	        setInterruption("connection-lost");
259	      } else if (streamingReply.current.trim()) {
260	        // Only on a build that actually completed: the route persists the
261	        // assistant reply in the success branch alone, so showing it after an
262	        // interruption would put a message on screen that a reload deletes.
263	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
264	      }
265	      if (touchedFiles) await refreshFiles();
266	    } catch (err) {
267	      if (stopRequested.current) {
268	        setInterruption("stopped");
269	        // Files the agent wrote before the abort are already committed to the
270	        // draft source, so pull them in — the Code view should show what is
271	        // really there, half-finished or not.
272	        if (touchedFiles) await refreshFiles().catch(() => {});
273	      } else if (err instanceof BuildServerError) {
274	        setError(err.message);
275	      } else if (streamStarted) {
276	        setInterruption("connection-lost");
277	      } else {
278	        setError(err instanceof Error ? err.message : "Something went wrong.");
279	      }
280	    } finally {
281	      abortRef.current = null;
282	      stopRequested.current = false;
283	      setStopping(false);
284	      setBusy(false);
285	      setStatus(null);
286	    }
287	  }
