301	  // Goes through fetch rather than a plain download link so a failure lands in
302	  // the same error strip as everything else here, instead of silently saving
303	  // the JSON error body as "slug.zip".
304	  async function downloadZip() {
305	    setDownloading(true);
306	    setError(null);
307	    try {
308	      const res = await fetch(`/api/projects/${props.projectId}/export`);
309	      if (!res.ok) {
310	        const body = await res.json().catch(() => ({}));
311	        throw new Error(body?.error ?? "Download failed.");
312	      }
313	      const url = URL.createObjectURL(await res.blob());
314	      const link = document.createElement("a");
315	      link.href = url;
316	      link.download = `${props.slug}.zip`;
317	      link.click();
318	      // The click hands the blob off asynchronously, so revoking in the same
319	      // tick can cancel the download in some browsers. Next tick is enough,
320	      // and skipping the revoke entirely would pin the archive in memory for
321	      // the life of the tab.
322	      setTimeout(() => URL.revokeObjectURL(url), 0);
