368	  // Global shortcuts. Deliberately three, all of them either an established
369	  // convention (⌘K / ⌃⇧P for a palette, "/" to jump to the input) or a
370	  // disambiguation of a key the box already owns (⌘⏎ builds even when Enter
371	  // has been handed over to the spec editor). Anything more inventive would
372	  // be a shortcut nobody discovers and everybody triggers by accident.
373	  // Bound only while the palette is CLOSED. While it is open the dialog owns
374	  // the keyboard outright — that is what makes the focus trap and the Escape
375	  // handling airtight, and it saves reading a "is it open" ref during render.
376	  useEffect(() => {
377	    if (paletteOpen) return;
378	    function onKeyDown(e: KeyboardEvent) {
379	      const mod = e.metaKey || e.ctrlKey;
380	      const openWith = (opener: HTMLElement | null) => {
381	        paletteReturn.current = opener;
382	        setPaletteOpen(true);
383	      };
384	      const active = document.activeElement;
385	      const focused = active instanceof HTMLElement && active !== document.body ? active : null;
386	
387	      if (mod && !e.altKey && e.key.toLowerCase() === "k") {
388	        e.preventDefault();
389	        openWith(focused);
390	        return;
391	      }
392	      if (mod && e.shiftKey && e.key.toLowerCase() === "p") {
393	        e.preventDefault();
394	        openWith(focused);
395	        return;
396	      }
397	      if (e.key === "/" && !mod && !e.altKey) {
398	        // "/" is a normal character inside a field — only a jump-to-input
399	        // shortcut when the user isn't already typing somewhere.
