"use client";

// TEMPORARY verification harness — deleted before this work is handed over.
// Renders the real Editor with fabricated props and a stubbed /api/generate so
// the keyboard, focus and interruption paths can be exercised in the running
// app without an account, a database row, or spending credits.

import { useState } from "react";
import Editor from "../Editor";

type Mode = "hang" | "silent-close" | "server-error";

if (typeof window !== "undefined" && !("__probeInstalled" in window)) {
  Object.assign(window, { __probeInstalled: true, __probeMode: "hang" as Mode });

  const realFetch = window.fetch.bind(window);

  window.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;

    if (url.includes("/api/generate")) {
      const mode = (window as unknown as { __probeMode: Mode }).__probeMode;
      const signal = init?.signal;
      const enc = new TextEncoder();
      let timer: ReturnType<typeof setInterval> | undefined;

      const body = new ReadableStream({
        start(controller) {
          const send = (o: unknown) => controller.enqueue(enc.encode(`data: ${JSON.stringify(o)}\n\n`));
          send({ type: "progress", text: "Reading the project" });
          send({ type: "file", path: "index.html", action: "write" });

          if (mode === "silent-close") {
            // The signature of a dropped pipe: closes with no done, no error.
            setTimeout(() => controller.close(), 300);
            return;
          }
          if (mode === "server-error") {
            setTimeout(() => {
              send({ type: "error", message: "Probe: the build failed on the server." });
              controller.close();
            }, 300);
            return;
          }
          let n = 0;
          timer = setInterval(() => send({ type: "progress", text: `Writing files (${++n})` }), 400);
          // Mirrors what a real aborted fetch does to its body.
          signal?.addEventListener("abort", () => {
            clearInterval(timer);
            controller.error(new DOMException("The user aborted a request.", "AbortError"));
          });
        },
        cancel() {
          clearInterval(timer);
        },
      });

      return new Response(body, {
        status: 200,
        headers: { "Content-Type": "text/event-stream" },
      });
    }

    if (url.includes("/api/projects/") || url.includes("/api/enhance")) {
      return new Response(JSON.stringify({ project: { files: [] }, builds: [], spec: "probe spec" }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      });
    }

    return realFetch(input as RequestInfo, init);
  };
}

export default function Probe() {
  const [first, setFirst] = useState(false);
  const [balance, setBalance] = useState(400);

  return (
    <div id="probe-root">
      <div id="probe-controls" style={{ position: "fixed", bottom: 0, right: 0, zIndex: 100, display: "flex", gap: 4, background: "#fff", border: "1px solid #ccc", padding: 4, fontSize: 11 }}>
        <button id="probe-first" onClick={() => setFirst((f) => !f)}>first={String(first)}</button>
        <button id="probe-bal" onClick={() => setBalance((b) => (b === 400 ? 30 : b === 30 ? 0 : 400))}>bal={balance}</button>
      </div>
      <Editor
        key={`${first}-${balance}`}
        projectId="probe-project"
        projectName="Probe Project"
        slug="probe"
        published={false}
        initialFiles={{ "index.html": "<h1>hi</h1>", "styles.css": "body{}" }}
        initialMessages={first ? [] : [{ role: "user", content: "make a coffee site" }, { role: "assistant", content: "Done." }]}
        initialBalance={balance}
        avgBuildCredits={25}
      />
    </div>
  );
}

