  key(ta,'P',{ctrlKey:true,shiftKey:true}); await wait(100);
  out.ctrlShiftP = { open: !!dlg(), active: document.activeElement.id };

  // 3. Ctrl+K while OPEN closes it (same chord toggles)
  key(document.activeElement,'k',{ctrlKey:true}); await wait(100);
  out.ctrlKClosesWhenOpen = { open: !!dlg(), active: document.activeElement.id };

  return JSON.stringify(out,null,1);
})()

