// Last-resort Escape. Everything above binds the keyboard to the dialog
// subtree, and the editor unbinds its own global shortcuts while the palette
// is open — so IF focus ever ends up outside the dialog, Escape has nobody
// listening and the modal becomes impossible to dismiss from the keyboard.
// The mousedown pin below closes the one route a user could take to get
// there, but "an undismissable modal" is a bad enough failure to be worth a
// second lock. This fires only when the dialog's own handler didn't:
// that one calls stopPropagation, which stops the native event before it
// reaches window.
useEffect(() => {
  const onEscape = (e: KeyboardEvent) => {
    if (e.key === "Escape") {
      e.preventDefault();
      onClose();
    }
  };
  window.addEventListener("keydown", onEscape);
  return () => window.removeEventListener("keydown", onEscape);
}, [onClose]);

const activeId = selected >= 0 && rows[selected] ? `kodely-cmd-${rows[selected].cmd.id}` : undefined;

