// TEMPORARY verification route — deleted before this work is handed over.
//
// /api/generate's Stop button rests entirely on one assumption: that aborting
// the client's fetch causes Next to fire cancel() on the route's
// ReadableStream, which is where that route calls abortController.abort().
// This route is the same shape, and records whether cancel() actually ran, so
// the assumption can be measured in this Next version and runtime instead of
// believed.

export const dynamic = "force-dynamic";

let cancelled = false;
let started = false;

export async function GET(req: Request) {
  const url = new URL(req.url);
  if (url.searchParams.get("check")) {
    return Response.json({ started, cancelled });
  }
  if (url.searchParams.get("reset")) {
    cancelled = false;
    started = false;
    return Response.json({ ok: true });
  }

  const encoder = new TextEncoder();
  let timer: ReturnType<typeof setInterval> | undefined;

  const stream = new ReadableStream({
    start(controller) {
      started = true;
      let n = 0;
      timer = setInterval(() => {
        try {
          controller.enqueue(encoder.encode(`data: {"type":"progress","text":"tick ${++n}"}\n\n`));
        } catch {
          // client gone
        }
      }, 150);
    },
    cancel() {
      cancelled = true;
      clearInterval(timer);
    },
  });

  return new Response(stream, {
    headers: { "Content-Type": "text/event-stream; charset=utf-8", "Cache-Control": "no-cache, no-transform" },
  });
}

