(async () => {
  const base = '/projects/x/probestream';
  const realFetch = window.fetch; // probe stub passes non-/api/ urls through
  const wait = ms => new Promise(r=>setTimeout(r,ms));
  await realFetch(base + '?reset=1');

  const ac = new AbortController();
  let readErr = null;
  const p = (async () => {
    const res = await realFetch(base, { signal: ac.signal });
    const reader = res.body.getReader();
    try { for (;;) { const {done} = await reader.read(); if (done) break; } }
    catch (e) { readErr = e.name + ': ' + e.message; }
  })();

  await wait(600);
  const before = await (await realFetch(base + '?check=1')).json();
  ac.abort();                       // <-- exactly what Editor.stop() does
  await p;
  await wait(500);
  const after = await (await realFetch(base + '?check=1')).json();

  return JSON.stringify({ beforeAbort: before, afterAbort: after, readerRejectedWith: readErr }, null, 1);
})()

